/* {{{ proto DOMText::__construct([string value]); */
PHP_METHOD(DOMText, __construct)
{
        xmlNodePtr nodep = NULL, oldnode = NULL;
        dom_object *intern;
        char *value = NULL;
        size_t value_len;

        if (zend_parse_parameters(ZEND_NUM_ARGS(), "|s", &value, &value_len) == FAILURE) {
